const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-06'; // GEE's end date is exclusive

  // 2. Data Acquisition
  const era5Daily = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('maximum_2m_air_temperature');

  // 3. Data Check
  const collectionSize = era5Daily.size().getInfo();
  if (collectionSize === 0) {
    console.log("No images found for the specified date range and location.");
    console.log("A: No");
    return;
  }
  console.log(`Found ${collectionSize} daily records.`);

  // Function to extract temperature at the point and convert K to C
  const getTemp = function(image) {
    const tempK = image.reduceRegion({
      reducer: ee.Reducer.first(),
      geometry: boston,
      scale: 1000 // A reasonable scale for this global dataset
    }).get('maximum_2m_air_temperature');
    // Check if the value is null before converting
    return ee.Algorithms.If(tempK, ee.Number(tempK).subtract(273.15), null);
  };

  // 4. Processing
  const tempList = era5Daily.toList(era5Daily.size()).map(function(image) {
    return getTemp(ee.Image(image));
  });

  // Check for nulls which would indicate a C3 failure
  const nullCount = tempList.filter(ee.Filter.eq('item', null)).size().getInfo();
  if (nullCount > 0) {
      console.log(`Error: Failed to extract temperature value on ${nullCount} day(s).`);
      console.log("C3: Calculation Failure");
      return;
  }

  const tempStats = tempList.reduce(ee.Reducer.minMax());
  const statsDict = tempStats.getInfo();

  // 5. Validation & Final Answer
  if (statsDict === null || !statsDict.hasOwnProperty('max') || !statsDict.hasOwnProperty('min')) {
    console.log("Error: Could not compute min/max statistics.");
    console.log("C3: Calculation Failure");
    return;
  }

  const maxTemp = statsDict.max;
  const minTemp = statsDict.min;
  const tempDifference = maxTemp - minTemp;

  console.log(`Maximum temperature (C): ${maxTemp.toFixed(2)}`);
  console.log(`Minimum temperature (C): ${minTemp.toFixed(2)}`);
  console.log(`Temperature difference (C): ${tempDifference.toFixed(2)}`);

  if (tempDifference >= 22) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
